local rows={}
for _,group in ipairs(groups)do
  for _,cell in ipairs(group.cells)do
    local row={}
    for key,value in pairs(group)do if key~="cells"then row[key]=value end end
    row.id,row.quadrant=cell[1],cell[2]
    rows[#rows+1]=row
  end
end
return rows
